/* ================= 偏好：Cookie A 优先（与 ai-shop / ip-check / 2fa 共享）+ localStorage 备份 ================= */
let LANG="zh", DARK=false, THEME_IDX=11;
function readCookieA(){
  try{
    const m=document.cookie.match(/(?:^|;\s*)A=([0-9]+)/);
    if(!m) return null;
    const v=m[1];
    if(v.length<3) return null;
    const lang=v[0]==="1"?"en":"zh";
    const dark=v[1]==="0";
    const themeNum=parseInt(v.slice(2),10);
    if(!(themeNum>=1&&themeNum<=12)) return null;
    return {lang,dark,theme:themeNum-1};
  }catch(e){return null}
}
function writeCookieA(){
  try{
    const v=(LANG==="en"?"1":"0")+(DARK?"0":"1")+String(THEME_IDX+1);
    const onDomain=location.hostname.endsWith("jpedu.asia");
    document.cookie="A="+v+"; Path=/; Max-Age=31536000; SameSite=Lax"+(onDomain?"; Domain=jpedu.asia":"");
  }catch(e){}
}
function savePrefs(){
  writeCookieA();
  try{localStorage.setItem("skill-prefs",JSON.stringify({lang:LANG,dark:DARK,theme:THEME_IDX}))}catch(e){}
}
function loadPrefs(){
  const a=readCookieA();
  if(a){LANG=a.lang;DARK=a.dark;THEME_IDX=a.theme;return}
  try{
    const raw=localStorage.getItem("skill-prefs");
    if(raw){const p=JSON.parse(raw);if(p){LANG=p.lang==="en"?"en":"zh";DARK=!!p.dark;if(Number.isInteger(p.theme)&&p.theme>=0&&p.theme<12)THEME_IDX=p.theme}}
  }catch(e){}
}

