/* ================= 过滤与折叠状态 ================= */
function applyFilter(){
  const q=document.getElementById("q").value.trim().toLowerCase();
  let total=0;
  document.querySelectorAll("section.board-sec").forEach(sec=>{
    let secVis=0;
    sec.querySelectorAll(".group").forEach(g=>{
      const items=g.querySelectorAll("[data-skill]"); let vis=0;
      items.forEach(el=>{const m=!q||el.dataset.skill.includes(q);el.classList.toggle("hidden",!m);if(m)vis++});
      if(items.length>0){
        g.classList.toggle("hidden",!!q&&vis===0);
        if(!(q&&vis===0)) secVis+=vis;
        const opened=q?vis>0:openGroups.has(g.id);
        g.classList.toggle("open",opened);
        const trig=g.querySelector(".group-trigger"); if(trig) trig.setAttribute("aria-expanded",String(opened));
      }
    });
    const note=sec.querySelector(".note-card"); if(note) note.classList.toggle("hidden",!!q);
    const secItems=sec.querySelectorAll("[data-skill]").length;
    sec.classList.toggle("hidden",!!q&&secItems>0&&secVis===0);
    total+=secVis;
  });
  const viz=document.getElementById("statsVizSection"); if(viz) viz.classList.toggle("hidden",!!q);
  const tip=document.getElementById("emptyTip"); if(tip) tip.classList.toggle("hidden",!q||total>0);
}

/* ================= 统计可视化（全部由真实 board 数据现算） ================= */
function installsTop5(b){
  return b.installs.map(e=>{
    const vals=[["skills.sh",e.installsSkillssh],["ClawHub",e.downloadsClawhub],["SkillHub CN",e.downloadsSkillhub]].filter(x=>x[1]!=null);
    if(!vals.length) return null;
    vals.sort((a,c)=>c[1]-a[1]);
    return {name:e.skill,plat:vals[0][0],val:vals[0][1]};
  }).filter(Boolean).sort((a,c)=>c.val-a.val).slice(0,5);
}
function sparkPoints(series,w,h,pad){
  const vals=series.filter(v=>v!=null);
  if(vals.length<2) return "";
  const min=Math.min(...vals), max=Math.max(...vals), span=(max-min)||1;
  const n=series.length;
  const pts=[];
  series.forEach((v,i)=>{if(v==null) return; const x=pad+(w-2*pad)*(n===1?0.5:i/(n-1)); const y=pad+(h-2*pad)*(1-(v-min)/span); pts.push(`${x.toFixed(1)},${y.toFixed(1)}`)});
  return pts.join(" ");
}
function renderStatsViz(){
  const container=document.getElementById("statsVizBody");
  if(!container||!board) return;
  const b=board, tt=T();
  const top5=installsTop5(b);
  const maxVal=top5.length?top5[0].val:1;
  const barHtml=`<div class="bar-chart-list" style="${VIZ==="both"?"margin-bottom:14px;":""}">${top5.map(x=>`
    <div class="bar-row" data-jump-sec="sec-01" data-jump-group="g-installs">
      <div class="bar-row-meta"><span class="bar-skill-name"><span>${esc(x.name)}</span><span class="bar-plat-tag">${esc(x.plat)}</span></span><span class="bar-skill-val">${fmt(x.val)}</span></div>
      <div class="bar-track"><div class="bar-fill" style="width:${Math.max(3,x.val/maxVal*100)}%;"></div></div>
    </div>`).join("")}</div>`;
  // 折线图（7 期历史，缺测断线不补 0）
  let lineHtml="";
  if(HIST&&HIST.dates.length>=2){
    const W=320,H=92,x0=10,x1=262,yT=10,yB=70;
    const seriesDefs=[
      {key:"trend",color:"#10B981",label:HIST.labels.trend},
      {key:"buzz",color:"#3B82F6",label:HIST.labels.buzz},
      {key:"repo",color:"#F59E0B",label:HIST.labels.repo}
    ];
    const lineFor=sd=>{
      const arr=HIST.series[sd.key]; if(!arr) return "";
      const vals=arr.filter(v=>v!=null); if(vals.length<2) return "";
      const min=Math.min(...vals),max=Math.max(...vals),span=(max-min)||1;
      const X=i=>x0+(x1-x0)*(arr.length===1?0:i/(arr.length-1));
      const Y=v=>yT+(yB-yT)*(1-(v-min)/span);
      let out="",run=[];
      const flush=()=>{if(run.length>=2) out+=`<polyline fill="none" stroke="${sd.color}" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" points="${run.join(" ")}"/>`; else if(run.length===1) out+=`<circle cx="${run[0].split(",")[0]}" cy="${run[0].split(",")[1]}" r="3" fill="${sd.color}"/>`; run=[]};
      arr.forEach((v,i)=>{if(v==null){flush()}else{run.push(`${X(i).toFixed(1)},${Y(v).toFixed(1)}`)}});
      flush();
      let lastIdx=-1; arr.forEach((v,i)=>{if(v!=null)lastIdx=i});
      if(lastIdx>=0) out+=`<circle cx="${X(lastIdx).toFixed(1)}" cy="${Y(arr[lastIdx]).toFixed(1)}" r="3.5" fill="${sd.color}"/><text x="${x1+8}" y="${(Y(arr[lastIdx])+3).toFixed(1)}" font-size="9.5" font-weight="800" fill="${sd.color}" font-family="ui-monospace,monospace">${esc(sd.label)}</text>`;
      return out;
    };
    const dateLabels=HIST.dates.map((d,i)=>{const x=x0+(x1-x0)*(HIST.dates.length===1?0:i/(HIST.dates.length-1));return `<text x="${(x-8).toFixed(1)}" y="86" font-size="8.5" fill="currentColor" opacity="${i===HIST.dates.length-1?"0.75":"0.45"}" ${i===HIST.dates.length-1?'font-weight="700"':""}>${esc(d.slice(5))}</text>`}).join("");
    lineHtml=`<div class="line-chart-container" style="${VIZ==="both"?"margin-bottom:12px;":""}"><div class="svg-chart-box">
      <div class="svg-chart-legend"><span style="font-weight:700;color:var(--text-primary);white-space:nowrap;">${esc(tt.lineTitle)}</span>
      <div class="legend-items">${seriesDefs.map(sd=>`<span><i class="legend-dot" style="background:${sd.color};"></i>${esc(HIST.names[sd.key]||"")}</span>`).join("")}</div></div>
      <svg viewBox="0 0 320 92" width="100%" height="92" style="overflow:visible;">
        <line x1="0" y1="18" x2="262" y2="18" stroke="currentColor" stroke-opacity="0.07" stroke-dasharray="3 3"/>
        <line x1="0" y1="44" x2="262" y2="44" stroke="currentColor" stroke-opacity="0.07" stroke-dasharray="3 3"/>
        <line x1="0" y1="70" x2="262" y2="70" stroke="currentColor" stroke-opacity="0.07"/>
        ${seriesDefs.map(lineFor).join("")}
        ${dateLabels}
      </svg></div></div>`;
  }
  // 数据表（highlights 四个维度的第一名，走势用同一份 7 期历史）
  const trendTop=b.trending[0], buzzTop=b.buzz[0], risingTop=b.rising[0];
  const repoGainTop=b.repos.reduce((m,e)=>(e.starsDelta1d!=null&&(m==null||e.starsDelta1d>m.starsDelta1d))?e:m,null);
  const rows=[];
  if(trendTop) rows.push({dim:tt.dims[0],name:trendTop.skill,plat:"",sub:`${fmt(trendTop.installs)}`,main:(trendTop.growthPct!=null?(trendTop.growthPct>0?"+":"")+trendTop.growthPct+"%":"—"),series:HIST?HIST.series.trend:null,color:"#10B981",sec:"sec-04",grp:"g-trend"});
  if(buzzTop) rows.push({dim:tt.dims[1],name:buzzTop.skill,plat:"",sub:tt.buzzSub(buzzTop),main:String(buzzTop.score),series:HIST?HIST.series.buzz:null,color:"#3B82F6",sec:"sec-04",grp:"g-buzz"});
  if(risingTop) rows.push({dim:tt.dims[2],name:risingTop.skill,plat:risingTop.platform||"",sub:tt.installsSub(risingTop.ageDays),main:risingTop.heat!=null?tt.heat(risingTop.heat):fmt(risingTop.value),series:HIST?HIST.series.rising:null,color:"#8B5CF6",sec:"sec-04",grp:"g-rising"});
  if(repoGainTop) rows.push({dim:tt.dims[3],name:repoGainTop.repo,plat:"GitHub",sub:tt.totalStars(fmt(repoGainTop.stars)),main:`+${fmt(repoGainTop.starsDelta1d)} ${tt.perDay}`,series:HIST?HIST.series.repoGain:null,color:"#F59E0B",sec:"sec-01",grp:"g-repos"});
  const tableHtml=`<table class="stat-data-table"><thead><tr><th>${esc(tt.tableHeads[0])}</th><th>${esc(tt.tableHeads[1])}</th><th>${esc(tt.tableHeads[2])}</th></tr></thead><tbody>
    ${rows.map(r=>`<tr data-jump-sec="${r.sec}" data-jump-group="${r.grp}">
      <td><div style="display:flex;align-items:center;gap:5px;min-width:0;"><span style="font-weight:800;font-family:ui-monospace,monospace;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;">${esc(r.name)}</span><span class="dim-tag">${esc(r.dim)}</span></div><div style="font-size:10.5px;color:var(--text-muted);margin-top:2px;overflow:hidden;text-overflow:ellipsis;">${esc(r.sub)}</div></td>
      <td>${r.series&&sparkPoints(r.series,60,22,2)?`<svg class="mini-spark-svg" viewBox="0 0 60 22"><polyline fill="none" stroke="${r.color}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" points="${sparkPoints(r.series,60,22,2)}"/></svg>`:""}</td>
      <td style="font-weight:800;color:var(--theme-accent);font-family:ui-monospace,monospace;">${esc(r.main)}</td>
    </tr>`).join("")}
    </tbody></table>`;
  if(VIZ==="bar") container.innerHTML=barHtml;
  else if(VIZ==="line") container.innerHTML=(lineHtml||"")+tableHtml;
  else if(VIZ==="table") container.innerHTML=tableHtml;
  else container.innerHTML=barHtml+lineHtml+tableHtml;
  const lineBtn=document.getElementById("vizLineBtn");
  if(lineBtn) lineBtn.classList.toggle("hidden",!(HIST&&HIST.dates.length>=2));
  container.querySelectorAll("[data-jump-sec]").forEach(el=>{
    el.addEventListener("click",()=>jumpToSection(el.getAttribute("data-jump-sec"),el.getAttribute("data-jump-group")));
  });
}
async function loadHistory(endDate){
  const key=endDate+"|"+(board?board.date:"");
  if(HIST_KEY===key&&HIST) return;
  HIST_KEY=key;
  try{
    const idx=DATES.indexOf(endDate);
    const dates=(idx>=0?DATES.slice(idx,idx+7):[endDate]).slice().reverse();
    const boards=await Promise.all(dates.map(async d=>{
      try{const r=await fetch(`data/boards/${d}.json?t=`+Date.now()); if(r.ok) return await r.json()}catch(e){}
      return null;
    }));
    if(!board||board.date!==endDate) return;
    const tName=board.trending[0]?.skill, bName=board.buzz[0]?.skill, rName=board.rising[0]?.skill;
    const repoTop=board.repos[0]?.repo;
    const gainTop=board.repos.reduce((m,e)=>(e.starsDelta1d!=null&&(m==null||e.starsDelta1d>m.starsDelta1d))?e:m,null);
    const pick=(list,key,name,field)=>{const e=(list||[]).find(x=>x[key]===name); return e?e[field]??null:null};
    HIST={
      dates:dates,
      names:{trend:tName||"",buzz:bName||"",repo:repoTop||""},
      labels:{
        trend:board.trending[0]?(board.trending[0].growthPct!=null?(board.trending[0].growthPct>0?"+":"")+board.trending[0].growthPct+"%":""):"",
        buzz:board.buzz[0]?`X ${board.buzz[0].x}${board.buzz[0].xTruncated?"+":""}`:"",
        repo:board.repos[0]&&board.repos[0].starsDelta1d!=null?`+${fmt(board.repos[0].starsDelta1d)}★`:""
      },
      series:{
        trend:boards.map(x=>x?pick(x.trending,"skill",tName,"installs"):null),
        buzz:boards.map(x=>x?pick(x.buzz,"skill",bName,"score"):null),
        rising:boards.map(x=>x?pick(x.rising,"skill",rName,"value"):null),
        repo:boards.map(x=>x?pick(x.repos,"repo",repoTop,"stars"):null),
        repoGain:boards.map(x=>x&&gainTop?pick(x.repos,"repo",gainTop.repo,"stars"):null)
      }
    };
    renderStatsViz();
  }catch(e){console.error(e)}
}
document.querySelectorAll(".viz-mode-btn").forEach(btn=>{
  btn.addEventListener("click",()=>{
    VIZ=btn.getAttribute("data-viz");
    document.querySelectorAll(".viz-mode-btn").forEach(el=>el.classList.toggle("active",el===btn));
    renderStatsViz();
  });
});

/* ================= 分区导航：历史快照与即时恢复 ================= */
let lastClickedSec=null;
let secNavCommit=0;
/* A section's clicked highlight must paint before pushState captures the
   outgoing history view; Back/Forward must not rewrite that highlight. */
function afterSecPaint(fn){
  requestAnimationFrame(()=>requestAnimationFrame(fn));
}
const secNavSession=Math.random().toString(36).slice(2);
try{
  history.scrollRestoration="manual";
  history.replaceState({secNavSession,y:window.scrollY},"",location.href);
}catch(e){}
function saveSecPosition(){
  const st=history.state, y=window.scrollY;
  if(!st||st.secNavSession!==secNavSession||st.y===y)return;
  try{history.replaceState({...st,y},"",location.href)}catch(e){}
}
function paintSec(secId,animate){
  document.querySelectorAll(".sec-sq-btn").forEach(b=>{
    const on=b.getAttribute("data-sec")===secId;
    b.classList.toggle("active",on);
    b.classList.toggle("pop",on&&animate!==false);
  });
}
function markSec(secId,animate){
  lastClickedSec=secId;
  paintSec(secId,animate);
}
function jumpToSection(secId,groupId){
  if(!document.getElementById(secId))return;
  markSec(secId);
  const nav=++secNavCommit;
  afterSecPaint(()=>{
    if(nav!==secNavCommit)return;
    const sec=document.getElementById(secId);if(!sec)return;
    saveSecPosition();
    try{history.pushState({secNavSession,y:window.scrollY},"","#"+secId)}catch(e){}
    /* Use fully expanded layout to preserve accurate navigation position. */
    if(groupId){
      const g=document.getElementById(groupId);
      if(g)g.classList.add("jump-open");
      openGroups.add(groupId);
    }else{
      sec.querySelectorAll(".group").forEach(g=>{g.classList.add("jump-open");openGroups.add(g.id)});
    }
    saveGroups(); applyFilter(); updateDockVisibility();
    sec.scrollIntoView({behavior:"smooth",block:"start"});
  });
}
function jumpToHash(){
  const id=(location.hash||"").slice(1); if(!id) return;
  const el=document.getElementById(id); if(!el) return;
  el.querySelectorAll(".group").forEach(g=>{
    g.classList.add("jump-open");
    if(!openGroups.has(g.id))openGroups.add(g.id);
  });
  applyFilter();
  el.scrollIntoView({block:"start",behavior:"instant"});
}
window.addEventListener("scroll",()=>{
  saveSecPosition();
  if(window.scrollY<=0&&location.hash){
    try{history.replaceState(history.state,"",location.pathname+location.search)}catch(e){}
  }
},{passive:true});
window.addEventListener("pageshow",e=>{if(!e.persisted)setTimeout(jumpToHash,60)});
window.addEventListener("popstate",e=>{
  secNavCommit++;
  const st=e.state;
  if(!st||st.secNavSession!==secNavSession)return;
  window.scrollTo({top:st.y||0,behavior:"instant"});
});
document.querySelectorAll(".sec-sq-btn").forEach(c=>{
  c.addEventListener("pointerdown",e=>{
    if(e.button===0)paintSec(c.getAttribute("data-sec"),false);
  });
  c.addEventListener("pointercancel",()=>paintSec(lastClickedSec,false));
  c.addEventListener("pointerup",e=>{
    if(!c.contains(document.elementFromPoint(e.clientX,e.clientY)))paintSec(lastClickedSec,false);
  });
  c.addEventListener("click",()=>jumpToSection(c.getAttribute("data-sec")));
});

