async function load(date){
  const btn=document.getElementById("reloadBtn");
  if(btn){btn.disabled=true;btn.classList.add("spinning")}
  try{
    const r=await fetch((date?`data/boards/${date}.json`:"data/board.json")+"?t="+Date.now());
    if(!r.ok) throw new Error();
    render(await r.json());
  }catch(e){
    console.error(e);
    if(!board) document.getElementById("sections").innerHTML=`<div class="empty-tip">${esc(T().loadFail)}</div>`;
  }finally{
    if(btn){btn.disabled=false;setTimeout(()=>btn.classList.remove("spinning"),520)}
  }
}
async function loadVideo(){
  try{
    const r=await fetch("data/video.json?t="+Date.now()); if(!r.ok) return;
    renderVideo(await r.json());
  }catch(e){console.error(e)}
}

