const floatingDockEl=document.getElementById("floatingQuickDock");
const DOCK_STORAGE_KEY="skills_floating_dock_pos_v3";
let dockWasDragged=false, dockStashedSide=null, dockSnapSide="right";
let cachedExpandedWidth=154, stashedIdleTimer=null;
function measureExpandedWidth(){ if(!dockStashedSide&&floatingDockEl.offsetWidth>60) cachedExpandedWidth=floatingDockEl.offsetWidth; return cachedExpandedWidth }
function scheduleStashedIdleDim(){ clearTimeout(stashedIdleTimer); floatingDockEl.classList.remove("stashed-idle"); if(dockStashedSide){ stashedIdleTimer=setTimeout(()=>{ if(dockStashedSide) floatingDockEl.classList.add("stashed-idle") },2000) } }
function applyDockState(left,top,stashedSide,autoMagneticSnap=true){
  dockStashedSide=stashedSide||null;
  floatingDockEl.classList.remove("stashed-left","stashed-right","edge-ready","stashed-idle");
  const w=measureExpandedWidth();
  const h=floatingDockEl.offsetHeight||38;
  const clampedTop=Math.min(Math.max(10,top),Math.max(10,window.innerHeight-h-10));
  if(dockStashedSide==="right"){
    dockSnapSide="right"; floatingDockEl.classList.add("stashed-right");
    floatingDockEl.style.left=(window.innerWidth-28)+"px"; floatingDockEl.style.top=clampedTop+"px"; floatingDockEl.style.right="auto"; floatingDockEl.style.bottom="auto";
    scheduleStashedIdleDim();
    return {left:window.innerWidth-28,top:clampedTop,stashedSide:"right",snapSide:"right"};
  }else if(dockStashedSide==="left"){
    dockSnapSide="left"; floatingDockEl.classList.add("stashed-left");
    floatingDockEl.style.left="0px"; floatingDockEl.style.top=clampedTop+"px"; floatingDockEl.style.right="auto"; floatingDockEl.style.bottom="auto";
    scheduleStashedIdleDim();
    return {left:0,top:clampedTop,stashedSide:"left",snapSide:"left"};
  }else{
    let targetLeft=left;
    if(autoMagneticSnap){
      const centerX=left+w/2;
      dockSnapSide=centerX<window.innerWidth/2?"left":"right";
      targetLeft=dockSnapSide==="left"?12:Math.max(12,window.innerWidth-w-12);
    }else{
      targetLeft=Math.min(Math.max(8,left),Math.max(8,window.innerWidth-w-8));
    }
    floatingDockEl.style.left=Math.round(targetLeft)+"px"; floatingDockEl.style.top=Math.round(clampedTop)+"px"; floatingDockEl.style.right="auto"; floatingDockEl.style.bottom="auto";
    return {left:Math.round(targetLeft),top:Math.round(clampedTop),stashedSide:null,snapSide:dockSnapSide};
  }
}
function saveDockState(o){ try{localStorage.setItem(DOCK_STORAGE_KEY,JSON.stringify(o))}catch(e){} }
function loadSavedDockPosition(){
  try{
    const raw=localStorage.getItem(DOCK_STORAGE_KEY); if(!raw) return;
    const parsed=JSON.parse(raw);
    if(parsed&&typeof parsed.top==="number"){
      dockSnapSide=parsed.snapSide||"right";
      const w=measureExpandedWidth();
      const defaultLeft=dockSnapSide==="left"?12:(window.innerWidth-w-12);
      applyDockState(parsed.left??defaultLeft,parsed.top,parsed.stashedSide||null,true);
    }
  }catch(e){}
}
function unstashDockFromEdge(){
  if(!dockStashedSide) return;
  const curTop=parseFloat(floatingDockEl.style.top)||(window.innerHeight-68);
  const side=dockStashedSide;
  dockStashedSide=null;
  floatingDockEl.classList.remove("stashed-left","stashed-right","stashed-idle");
  const w=measureExpandedWidth();
  const targetLeft=side==="right"?Math.max(12,window.innerWidth-w-12):12;
  saveDockState(applyDockState(targetLeft,curTop,null,true));
}
(function initDraggableDock(){
  let isDragging=false,startX=0,startY=0,initialLeft=0,initialTop=0,currentDragLeft=0,currentDragTop=0,lastClientX=0,lastMoveTime=0,velocityX=0,pendingStashSide=null;
  floatingDockEl.addEventListener("pointerdown",e=>{
    if(e.button&&e.button!==0) return;
    isDragging=true; dockWasDragged=false; pendingStashSide=null;
    startX=e.clientX; startY=e.clientY; lastClientX=e.clientX; lastMoveTime=performance.now(); velocityX=0;
    clearTimeout(stashedIdleTimer); floatingDockEl.classList.remove("stashed-idle"); measureExpandedWidth();
    const rect=floatingDockEl.getBoundingClientRect();
    initialLeft=rect.left; initialTop=rect.top; currentDragLeft=initialLeft; currentDragTop=initialTop;
    try{floatingDockEl.setPointerCapture(e.pointerId)}catch(_){}
  });
  floatingDockEl.addEventListener("pointermove",e=>{
    if(!isDragging) return;
    const now=performance.now(); const dt=Math.max(1,now-lastMoveTime);
    const instantVx=(e.clientX-lastClientX)/dt;
    velocityX=velocityX*0.4+instantVx*0.6;
    lastClientX=e.clientX; lastMoveTime=now;
    const dx=e.clientX-startX, dy=e.clientY-startY;
    if(!dockWasDragged&&Math.hypot(dx,dy)>4){ dockWasDragged=true; floatingDockEl.classList.add("dragging") }
    if(!dockWasDragged) return;
    if(dockStashedSide==="right"){
      if(dx<-14){ dockStashedSide=null; floatingDockEl.classList.remove("stashed-right"); const w=measureExpandedWidth(); initialLeft=e.clientX-w*0.65-dx }
      else{ const h=floatingDockEl.offsetHeight||46; currentDragTop=Math.min(Math.max(10,initialTop+dy),window.innerHeight-h-10); floatingDockEl.style.top=Math.round(currentDragTop)+"px"; return }
    }else if(dockStashedSide==="left"){
      if(dx>14){ dockStashedSide=null; floatingDockEl.classList.remove("stashed-left"); const w=measureExpandedWidth(); initialLeft=e.clientX-w*0.35-dx }
      else{ const h=floatingDockEl.offsetHeight||46; currentDragTop=Math.min(Math.max(10,initialTop+dy),window.innerHeight-h-10); floatingDockEl.style.top=Math.round(currentDragTop)+"px"; return }
    }
    const w=cachedExpandedWidth, h=floatingDockEl.offsetHeight||38;
    const rawLeft=initialLeft+dx, rawTop=initialTop+dy;
    currentDragTop=Math.min(Math.max(10,rawTop),Math.max(10,window.innerHeight-h-10));
    const minInScreen=0, maxInScreen=window.innerWidth-w;
    if(rawLeft<minInScreen){ const over=minInScreen-rawLeft; currentDragLeft=-Math.min(w*0.48,over*0.45) }
    else if(rawLeft>maxInScreen){ const over=rawLeft-maxInScreen; currentDragLeft=maxInScreen+Math.min(w*0.48,over*0.45) }
    else{ currentDragLeft=rawLeft }
    if(currentDragLeft>=maxInScreen+16){ pendingStashSide="right"; floatingDockEl.classList.add("edge-ready") }
    else if(currentDragLeft<=-16){ pendingStashSide="left"; floatingDockEl.classList.add("edge-ready") }
    else{ pendingStashSide=null; floatingDockEl.classList.remove("edge-ready") }
    floatingDockEl.style.left=Math.round(currentDragLeft)+"px"; floatingDockEl.style.top=Math.round(currentDragTop)+"px"; floatingDockEl.style.right="auto"; floatingDockEl.style.bottom="auto";
  });
  const endDockDrag=e=>{
    if(!isDragging) return;
    isDragging=false; floatingDockEl.classList.remove("dragging","edge-ready");
    try{floatingDockEl.releasePointerCapture(e.pointerId)}catch(_){}
    if(dockWasDragged){
      const w=cachedExpandedWidth, maxInScreen=window.innerWidth-w;
      if(!pendingStashSide&&!dockStashedSide){
        if(currentDragLeft>=maxInScreen-6&&velocityX>0.35) pendingStashSide="right";
        else if(currentDragLeft<=6&&velocityX<-0.35) pendingStashSide="left";
      }
      saveDockState(applyDockState(currentDragLeft,currentDragTop,pendingStashSide||dockStashedSide,true));
      setTimeout(()=>{dockWasDragged=false},60);
    }else if(dockStashedSide){ unstashDockFromEdge() }
  };
  floatingDockEl.addEventListener("pointerup",endDockDrag);
  floatingDockEl.addEventListener("pointercancel",endDockDrag);
  window.addEventListener("resize",()=>{
    const w=measureExpandedWidth();
    const curTop=parseFloat(floatingDockEl.style.top)||(window.innerHeight-68);
    const targetLeft=dockSnapSide==="left"?12:Math.max(12,window.innerWidth-w-12);
    applyDockState(targetLeft,curTop,dockStashedSide,true);
  });
})();
function updateDockVisibility(){
  let hasCustomPos=false;
  try{hasCustomPos=!!localStorage.getItem(DOCK_STORAGE_KEY)}catch(e){}
  floatingDockEl.classList.toggle("visible",hasCustomPos||window.scrollY>120||openGroups.size>0);
}
window.addEventListener("scroll",updateDockVisibility,{passive:true});
document.getElementById("btnCollapseAllGroups").addEventListener("click",e=>{
  if(dockWasDragged){e.preventDefault();e.stopPropagation();return}
  openGroups.clear(); saveGroups();
  applyFilter(); updateDockVisibility();
});
document.getElementById("btnBackToTop").addEventListener("click",e=>{
  if(dockWasDragged){e.preventDefault();e.stopPropagation();return}
  window.scrollTo({top:0,behavior:"smooth"});
});

/* ================= 初始化 ================= */
(async()=>{
  loadPrefs();
  applyTheme(THEME_IDX,false);
  setDark(DARK,false);
  applyLang(false);
  loadSavedDockPosition();
  updateDockVisibility();
  try{DATES=await (await fetch("data/dates.json?t="+Date.now())).json()}catch(e){DATES=[]}
  const sel=document.getElementById("dateSel");
  sel.innerHTML=DATES.map(d=>`<option value="${d}">${d}${T().periodSuffix}</option>`).join("");
  sel.classList.remove("skelbar");
  sel.addEventListener("change",()=>load(sel.value));
  document.getElementById("reloadBtn").addEventListener("click",()=>load(sel.value||null));
  await load(DATES[0]||null);
  if(DATES[0]) sel.value=DATES[0];
  loadVideo();
  updateDockVisibility();
})();

